type ItemId = "healing" | "mana" | "bomb" | "ward" | "watchblade" | "lorancloak" | "astralring" | "obsidian" | "goblinmark" | "greaterheal" | "moonward" | "starlance" | "mendercloak" | "ravenseal";

type Draft = { name: string; classId: ClassId; originId: OriginId; appearanceId: AppearanceId };
type Intent = { id: string; label: string; description: string; min: number; max: number; icon: typeof Sword };
