type Log = { id: number; actor: string; message: string; tone: "hero" | "enemy" | "system" };
type Hero = { hp: number; mana: number; xp: number; gold: number; level: number; attributePoints: number; talentPoints: number; attributes: Record<AttributeKey, number>; talents: string[]; statuses: StatusEffect[] };
