type WorldProgress = { reputation: number; campRank: number; codex: string[]; achievements: string[]; completedMissions: string[]; events: string[]; missionPath?: MissionPath; checkpoint: Checkpoint };
type CharacterSummary = { id: number; characterName: string; classId: string; originId: string; appearanceId: string; updatedAt: Date | string };
type SavedGame = {
  draft: Draft; started: boolean; encounterIndex: number; hero: Hero;
  enemyHp: number; battleState: BattleState; turn: TurnOwner; intentId: string; inventory: Item[];
  selectedId: ItemId; equipped: Partial<Record<Slot, ItemId>>; logs: Log[]; merchantLine: string; enemyStatuses?: StatusEffect[]; world?: WorldProgress;
};

